- name: Metadata585 - Read-only existing D1 repair preparation and live preflight
  if: env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_SOURCE_ACTIVE == 'true' && env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_PHASE == 'installed' && steps.current-private-publish.outcome == 'success' && steps.established-native-current-origin-checkpoint-publish.outcome == 'success'
  timeout-minutes: 5
  shell: bash
  env:
    SUPABASE_ACCESS_TOKEN: ${{ secrets.SUPABASE_ACCESS_TOKEN }}
    SUPABASE_PROJECT_ID: afqhhdrkjfjtpadntdzo
    SUPABASE_URL: ${{ secrets.SUPABASE_URL }}
    SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}
    SUPABASE_PUBLISHABLE_KEY: ${{ secrets.SUPABASE_PUBLISHABLE_KEY }}
    CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
    CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
    CLOUDFLARE_TRIP_GATEWAY_URL: ${{ secrets.CLOUDFLARE_TRIP_GATEWAY_URL }}
    TRIP_GATEWAY_SHARED_SECRET: ${{ secrets.TRIP_GATEWAY_SHARED_SECRET }}
    TRIP_WRANGLER_CONFIG_PATH: /tmp/ravradar-account-statistics-assistant-repair-wrangler.json
    TRIP_STORAGE_OWNER_EXPORT_UPGRADE: '0'
    TRIP_STORAGE_OWNER_ERASURE_GUARD: '0'
    TRIP_STORAGE_UPGRADE_PREFLIGHT: '0'
    EXPECTED_TRIP_STORAGE_MODE: d1
  run: |
    set -euo pipefail
    if [ "$TRIP_STORAGE_OWNER_EXPORT_UPGRADE" = "1" ]; then
      node scripts/prepare-cloudflare-trip-storage.mjs --existing-owner-export-upgrade-plan
    else
      node scripts/prepare-cloudflare-trip-storage.mjs --existing-worker-repair
    fi
    node --input-type=module <<'OFF_NODE'
    import fs from 'node:fs';
    const file=process.env.TRIP_WRANGLER_CONFIG_PATH,config=JSON.parse(fs.readFileSync(file,'utf8'));
    if(Object.hasOwn(config,'vars'))throw new Error('UNEXPECTED_WORKER_VARS');
    config.vars={TRIP_AGGREGATE_ENABLED:'false'};
    fs.writeFileSync(file,JSON.stringify(config)+'\n',{mode:0o600});
    OFF_NODE
    node scripts/audit-cloudflare-trip-storage.mjs
    node scripts/verify-trip-storage-edge.mjs
    node scripts/verify-cloudflare-trip-gateway.mjs

# Metadata snapshot only: atomicWriterLease=false, not physical drain.
- name: Metadata585 - Quiesce the existing D1 installation
  id: account_statistics_assistant_repair_quiesce
  if: env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_SOURCE_ACTIVE == 'true' && env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_PHASE == 'installed' && steps.current-private-publish.outcome == 'success' && steps.established-native-current-origin-checkpoint-publish.outcome == 'success'
  timeout-minutes: 5
  shell: bash
  env:
    SUPABASE_ACCESS_TOKEN: ${{ secrets.SUPABASE_ACCESS_TOKEN }}
    SUPABASE_PROJECT_ID: afqhhdrkjfjtpadntdzo
    SUPABASE_URL: ${{ secrets.SUPABASE_URL }}
    SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}
    SUPABASE_PUBLISHABLE_KEY: ${{ secrets.SUPABASE_PUBLISHABLE_KEY }}
    CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
    CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
    CLOUDFLARE_TRIP_GATEWAY_URL: ${{ secrets.CLOUDFLARE_TRIP_GATEWAY_URL }}
    TRIP_GATEWAY_SHARED_SECRET: ${{ secrets.TRIP_GATEWAY_SHARED_SECRET }}
    TRIP_WRANGLER_CONFIG_PATH: /tmp/ravradar-account-statistics-assistant-repair-wrangler.json
    TRIP_STORAGE_OWNER_EXPORT_UPGRADE: '0'
    TRIP_STORAGE_OWNER_ERASURE_GUARD: '0'
    TRIP_STORAGE_UPGRADE_PREFLIGHT: '0'
  run: |
    node --input-type=module <<'REPAIR_NODE'
    import { execFileSync } from 'node:child_process';
    import fs from 'node:fs';
    const env = process.env;
    function run(label, command, args, options = {}) {
      try { return execFileSync(command, args, { encoding: 'utf8', stdio: 'pipe', timeout: 180000,
        maxBuffer: 1024 * 1024, ...options }); }
      catch { throw new Error('TRIP_REPAIR_' + label); }
    }
    function exactMain() {
      if (env.GITHUB_REF !== 'refs/heads/main' || !/^[a-f0-9]{40}$/.test(env.GITHUB_SHA || '')) throw new Error('TRIP_REPAIR_MAIN_INVALID');
      run('MAIN_FETCH', 'git', ['fetch', '--no-tags', '--depth=1', 'origin', '+refs/heads/main:refs/remotes/origin/main']);
      for (const ref of ['HEAD^{commit}', 'origin/main^{commit}']) {
        if (run('MAIN_READ', 'git', ['rev-parse', ref]).trim() !== env.GITHUB_SHA) throw new Error('TRIP_REPAIR_MAIN_CHANGED');
      }
    }
    function edge(mode) {
      run('EDGE_ATTESTATION', 'node', ['scripts/verify-trip-storage-edge.mjs'], { env: { ...env, EXPECTED_TRIP_STORAGE_MODE: mode } });
    }
    function worker(expectedVersion) {
      run('WORKER_ATTESTATION', 'node', ['scripts/verify-cloudflare-trip-gateway.mjs'],
        expectedVersion === undefined ? {} : { env: { ...env, EXPECTED_TRIP_WORKER_VERSION: expectedVersion } });
    }
    function lease(minimumSeconds) {
      const deadline = Number(env.REPAIR_LEASE_DEADLINE);
      if (!Number.isSafeInteger(deadline) || deadline - Date.now() < minimumSeconds * 1000
        || deadline - Date.now() > 20 * 60000) throw new Error('TRIP_REPAIR_LEASE_INVALID');
    }
    function output(name, value) { fs.appendFileSync(env.GITHUB_OUTPUT, name + '=' + value + '\n'); }
    exactMain();
    output('intent', 'true');
    const deadline = Date.now() + 20 * 60000;
    output('deadline', String(deadline));
    run('MAINTENANCE', 'supabase', ['secrets', 'set', '--project-ref', env.SUPABASE_PROJECT_ID,
      'TRIP_STORAGE_MODE=maintenance:' + new Date(deadline).toISOString()]);
    edge('maintenance');
    run('DRAIN', 'sleep', ['20']);
    REPAIR_NODE

