    TRIP_STORAGE_OWNER_EXPORT_UPGRADE: '0'
    TRIP_STORAGE_OWNER_ERASURE_GUARD: '0'
    TRIP_STORAGE_UPGRADE_PREFLIGHT: '0'
    REPAIR_LEASE_DEADLINE: ${{ steps.account_statistics_assistant_repair_quiesce.outputs.deadline }}
  run: |
    node --input-type=module <<'REPAIR_NODE'
    import { execFileSync } from 'node:child_process';
    import fs from 'node:fs';
    const env = process.env;
    function run(label, command, args, options = {}) {
      try { return execFileSync(command, args, { encoding: 'utf8', stdio: 'pipe', timeout: 180000,
        maxBuffer: 1024 * 1024, ...options }); }
      catch { throw new Error('TRIP_REPAIR_' + label); }
    }
    function exactMain() {
      if (env.GITHUB_REF !== 'refs/heads/main' || !/^[a-f0-9]{40}$/.test(env.GITHUB_SHA || '')) throw new Error('TRIP_REPAIR_MAIN_INVALID');
      run('MAIN_FETCH', 'git', ['fetch', '--no-tags', '--depth=1', 'origin', '+refs/heads/main:refs/remotes/origin/main']);
      for (const ref of ['HEAD^{commit}', 'origin/main^{commit}']) {
        if (run('MAIN_READ', 'git', ['rev-parse', ref]).trim() !== env.GITHUB_SHA) throw new Error('TRIP_REPAIR_MAIN_CHANGED');
      }
    }
    function edge(mode) {
      run('EDGE_ATTESTATION', 'node', ['scripts/verify-trip-storage-edge.mjs'], { env: { ...env, EXPECTED_TRIP_STORAGE_MODE: mode } });
    }
    function worker(expectedVersion) {
      run('WORKER_ATTESTATION', 'node', ['scripts/verify-cloudflare-trip-gateway.mjs'],
        expectedVersion === undefined ? {} : { env: { ...env, EXPECTED_TRIP_WORKER_VERSION: expectedVersion } });
    }
    function lease(minimumSeconds) {
      const deadline = Number(env.REPAIR_LEASE_DEADLINE);
      if (!Number.isSafeInteger(deadline) || deadline - Date.now() < minimumSeconds * 1000
        || deadline - Date.now() > 20 * 60000) throw new Error('TRIP_REPAIR_LEASE_INVALID');
    }
    function output(name, value) { fs.appendFileSync(env.GITHUB_OUTPUT, name + '=' + value + '\n'); }
    worker();
    if (env.TRIP_STORAGE_OWNER_EXPORT_UPGRADE === '1') {
      run('UPGRADE_READBACK', 'node', ['scripts/prepare-cloudflare-trip-storage.mjs', '--existing-owner-export-upgrade-check']);
    }
    exactMain();
    lease(600);
    import { deployTripWorker } from './scripts/lib/trip-worker-deploy-process.mjs';
    output('deploy_intent', 'true');
    let deployed;
    try {
      const result = await deployTripWorker({ configPath: env.TRIP_WRANGLER_CONFIG_PATH, env });
      if (result?.terminationConfirmed !== true) throw new Error('TRIP_REPAIR_WORKER_DEPLOY');
      output('deploy_stopped', 'true');
      deployed = result.stdout;
    } catch (error) {
      if (error?.terminationConfirmed === true) output('deploy_stopped', 'true');
      throw new Error('TRIP_REPAIR_WORKER_DEPLOY');
    }
    const versions = [...deployed.matchAll(/^Current Version ID: ([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})\s*$/gim)];
    if (versions.length !== 1) throw new Error('TRIP_REPAIR_DEPLOY_IDENTITY_MISSING');
    worker(versions[0][1]);
    output('version', versions[0][1]);
    console.log('Worker repair source=' + env.GITHUB_SHA + ' version=' + versions[0][1]);
    REPAIR_NODE

