- name: Require unchanged central-public authority before saved checkpoint reconciliation
  if: (steps.saved-last-mile-source.outputs.required == 'true') || (env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_SOURCE_ACTIVE == 'true' && inputs.publish_newest_saved_weather == true)
  shell: bash
  env:
    OPERATIONAL_ACTION: ${{ steps.operational-action.outputs.action }}
  run: |
    set -euo pipefail
    node --input-type=module <<'NODE'
    import assert from 'node:assert/strict';
    import fs from 'node:fs/promises';
    import path from 'node:path';
    import { canonicalPublicRuntimeJson } from './js/core/ravscore-public-runtime-contract.js';
    import { assertZoneRegistryVersionOnly } from './scripts/prepare-code-only-public-runtime.mjs';
    import { ravScoreSamplingContextKey } from './scripts/lib/ravscore-sampling-context.mjs';
    import { sha256Text } from './scripts/public-conditions-lib.mjs';
    import { assertSavedPrivateRuntimeCheckpointReconcileRequest } from './scripts/reconcile-private-runtime-checkpoint.mjs';
    assertSavedPrivateRuntimeCheckpointReconcileRequest();
    assert(path.isAbsolute(process.env.GITHUB_WORKSPACE ?? ''));
    assert(path.isAbsolute(process.env.RAVRADAR_CODE_ONLY_PUBLIC_SNAPSHOT ?? ''));
    const read = async (file, maximum) => {
      const stat = await fs.lstat(file);
      assert(stat.isFile() && !stat.isSymbolicLink() && stat.size > 0 && stat.size <= maximum,
        'SAVED_LAST_MILE_AUTHORITY_FILE');
      const text = await fs.readFile(file, 'utf8');
      assert.equal(Buffer.byteLength(text), stat.size, 'SAVED_LAST_MILE_AUTHORITY_FILE_CHANGED');
      return { text, value: JSON.parse(text) };
    };
    const root = process.env.GITHUB_WORKSPACE, snapshot = process.env.RAVRADAR_CODE_ONLY_PUBLIC_SNAPSHOT;
    const [manifest, activeCoastal, publicCoastal, activeZones, publicZones, activeRouting, publicRouting, version] = await Promise.all([
      read(path.join(snapshot, 'manifest.json'), 1024 * 1024),
      read(path.join(root, 'data/live/coastal-parts-v2.json'), 16 * 1024 * 1024),
      read(path.join(snapshot, 'coastal-parts-v2.json'), 16 * 1024 * 1024),
      read(path.join(root, 'data/zones.geojson'), 32 * 1024 * 1024),
      read(path.join(snapshot, 'zones.geojson'), 32 * 1024 * 1024),
      read(path.join(root, 'data/water-level-station-routing.json'), 4 * 1024 * 1024),
      read(path.join(snapshot, 'water-level-station-routing.json'), 4 * 1024 * 1024),
      read(path.join(root, 'version.json'), 16 * 1024),
    ]);
    assert.equal(manifest.value.complete, true);
    assert.equal(manifest.value.zoneCount, 210); assert.equal(manifest.value.coastalPartCount, 673);
    for (const [source, digest, bytes] of [[publicCoastal, 'coastalPartsSha256', 'coastalPartsBytes'],
      [publicZones, 'zoneRegistrySha256', 'zoneRegistryBytes']]) {
      assert.equal(sha256Text(source.text), manifest.value[digest], 'SAVED_LAST_MILE_PUBLIC_MANIFEST_DIGEST');
      assert.equal(Buffer.byteLength(source.text), manifest.value[bytes], 'SAVED_LAST_MILE_PUBLIC_MANIFEST_SIZE');
    }
    for (const { value } of [activeCoastal, publicCoastal]) {
      assert.equal(value.schemaVersion, 2); assert.equal(value.enabled, true);
      assert.equal(value.zoneCount, 210); assert.equal(value.partCount, 673);
      const parts = Object.entries(value.zones).flatMap(([zoneId, rows]) => rows.map(part => ({ ...part, zoneId })));
      assert.equal(Object.keys(value.zones).length, 210); assert.equal(parts.length, 673);
      assert.equal(new Set(parts.map(part => part.partId)).size, 673);
      for (const part of parts) ravScoreSamplingContextKey(part);
    }
    // Only the registry clock is non-authoritative. Every actual point,
    // geometry, owner, source identity, direction and coverage field stays.
    const { generatedAt: activeClock, ...activeAuthority } = activeCoastal.value;
    const { generatedAt: publicClock, ...publicAuthority } = publicCoastal.value;
    assert(canonicalPublicRuntimeJson(activeAuthority) === canonicalPublicRuntimeJson(publicAuthority),
      'SAVED_LAST_MILE_COASTAL_AUTHORITY_CHANGED');
    assertZoneRegistryVersionOnly(publicZones.value, activeZones.value, version.value.version);
    assert.equal(activeRouting.value.schemaVersion, 1); assert.equal(publicRouting.value.schemaVersion, 1);
    // The normal routing consumers use zones, not the top save timestamp.
    const { updatedAt: activeSavedAt, ...activeRoute } = activeRouting.value;
    const { updatedAt: publicSavedAt, ...publicRoute } = publicRouting.value;
    assert(canonicalPublicRuntimeJson(activeRoute) === canonicalPublicRuntimeJson(publicRoute),
      'SAVED_LAST_MILE_WATER_ROUTING_CHANGED');
    console.log('Saved public geometry, point identities and routing match actual central authority; no data changed.');
    NODE

