- name: Require already-installed last-mile saved-weather contracts without replay
  if: steps.saved-last-mile-source.outputs.required == 'true'
  shell: bash
  env:
    OPERATIONAL_ACTION: ${{ steps.operational-action.outputs.action }}
    SUPABASE_ACCESS_TOKEN: ${{ secrets.SUPABASE_ACCESS_TOKEN }}
    SUPABASE_DB_PASSWORD: ${{ secrets.SUPABASE_DB_PASSWORD }}
    SUPABASE_URL: ${{ secrets.SUPABASE_URL }}
    SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}
  run: |
    set -euo pipefail
    (cd "${{ steps.migration-view.outputs.workdir }}" && supabase db push --linked --dry-run --skip-vault) 2>&1 | tee "$RUNNER_TEMP/code-only-saved-last-mile-dry-run.txt"
    env -u SUPABASE_DB_PASSWORD node --input-type=module <<'NODE'
    import assert from 'node:assert/strict';
    import fs from 'node:fs/promises';
    import { assertSavedPrivateRuntimeCheckpointReconcileRequest } from './scripts/reconcile-private-runtime-checkpoint.mjs';
    import { assertLastMileEnclosureMigrationsApplied, assertLastMileEnclosureMigrationPlan,
      verifyIntegratedDatabaseReadback } from './scripts/integrated-cutover-readiness.mjs';
    import { verifyInstalledStatisticsPreferenceRevisionSchema } from './scripts/verify-account-assistant-schema.mjs';
    assertSavedPrivateRuntimeCheckpointReconcileRequest();
    const migrationListText = await fs.readFile(process.env.RUNNER_TEMP + '/code-only-migrations-before.txt', 'utf8');
    const dryRunText = await fs.readFile(process.env.RUNNER_TEMP + '/code-only-saved-last-mile-dry-run.txt', 'utf8');
    assertLastMileEnclosureMigrationsApplied(migrationListText);
    const plan = await assertLastMileEnclosureMigrationPlan({ migrationListText, dryRunText,
      migrationsDirectory: process.env.RAVRADAR_LAST_MILE_ENCLOSURE_MIGRATIONS_DIR });
    assert.deepEqual(plan.pendingVersions, []);
    await verifyIntegratedDatabaseReadback({ url: process.env.SUPABASE_URL,
      serviceRoleKey: process.env.SUPABASE_SERVICE_ROLE_KEY, sourcePhase: 'last-mile-enclosure' });
    const schema = await verifyInstalledStatisticsPreferenceRevisionSchema({ accessToken: process.env.SUPABASE_ACCESS_TOKEN });
    assert.equal(schema.status, 'ACCOUNT_STATISTICS_REVISION_SCHEMA_MATCH');
    assert.equal(schema.schemaVersion, 2);
    await fs.appendFile(process.env.GITHUB_ENV, 'RAVRADAR_LAST_MILE_ENCLOSURE_PHASE=installed\n');
    NODE

edits.current:
- name: Select exact new metadata SQL phase from actual linked history
  if: env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_SOURCE_ACTIVE == 'true'
  run: >-
    node scripts/verify-account-statistics-assistant-plan.mjs --select
    --migration-list "$RUNNER_TEMP/code-only-migrations-before.txt"

- name: Require originals before the pending assistant binding
  if: (((steps.operational-action.outputs.action == 'integrated' || steps.operational-action.outputs.action == 'integrated-historical-maintenance') && (inputs.restart_archived_weather != true)) && (steps.saved-last-mile-source.outputs.required != 'true')) && (env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_SOURCE_ACTIVE != 'true')
  shell: bash
  run: |
    set -euo pipefail
    node --input-type=module <<'NODE'
    import fs from 'node:fs';
    import { LATEST_REQUIRED_CUTOVER_MIGRATION as latest, TRIP_BINDING_POLICY_SOURCE_MIGRATION as userdataPolicy, parseSupabaseMigrationList } from './scripts/integrated-cutover-readiness.mjs';
    const rows = parseSupabaseMigrationList(fs.readFileSync(`${process.env.RUNNER_TEMP}/code-only-migrations-before.txt`, 'utf8'));
    const required = latest.version === '20261010120000' && !rows.some(row => row.remote === latest.version);
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_ASSISTANT_PREWRITE_REQUIRED=${required}\n`);
    const userdataPending = !rows.some(row => row.remote === userdataPolicy.version);
    const optedIn = process.env.RAVRADAR_USERDATA_UPGRADE_OPT_IN === 'true';
    if (userdataPending && !optedIn) throw new Error('Pending userdata binding requires explicit existing-owner-export opt-in');
    if (optedIn && (latest.version !== '20261010130000' || !userdataPending
        || !rows.some(row => row.remote === '20261005000000')
        || rows.some(row => row.remote > '20261005000000'))) {
      throw new Error('Userdata upgrade requires installed current050000 and sole pending130000; no intermediary or automatic replay');
    }
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_USERDATA_PREWRITE_REQUIRED=${optedIn && userdataPending}\n`);
    // A later checkpoint-only migration must not suppress the installed
    // userdata storage readback or replay the one-time userdata upgrade.
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_USERDATA_FINAL_REQUIRED=${userdataPolicy.version === '20261010130000'}\n`);
    // This implementation-only repair must never select the normal
    // continuation-repair/recomputation branch for archived weather.
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_CHECKPOINT_CAS_METADATA_ONLY=${latest.version === '20261012200000'}\n`);
    const accountCurrent = latest.version === '20261013210000';
    const accountPending = accountCurrent && !rows.some(row => row.remote === latest.version);
    const accountOptIn = process.env.RAVRADAR_ACCOUNT_ASSISTANT_UPGRADE_OPT_IN === 'true';
    if (accountPending && !accountOptIn) throw new Error('Pending account/assistant successor requires its named opt-in');
    if (accountOptIn && (!accountPending || optedIn
        || !rows.some(row => row.remote === '20261012200000')
        || rows.some(row => row.remote > '20261012200000'))) {
      throw new Error('Account/assistant upgrade requires installed200000 and sole pending20261013210000; no replay');
    }
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_ACCOUNT_ASSISTANT_PREWRITE_REQUIRED=${accountOptIn && accountPending}\n`);
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_ACCOUNT_ASSISTANT_METADATA_ONLY=${accountCurrent}\n`);
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_ACCOUNT_ASSISTANT_FINAL_REQUIRED=${accountCurrent}\n`);
    NODE

