edits.current:
- name: Select only the exact installed last-mile saved-weather source
  id: saved-last-mile-source
  if: (inputs.publish_newest_saved_weather == true) && (env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_SOURCE_ACTIVE != 'true')
  shell: bash
  env:
    OPERATIONAL_ACTION: ${{ steps.operational-action.outputs.action }}
  run: |
    set -euo pipefail
    node --input-type=module <<'NODE'
    import assert from 'node:assert/strict';
    import fs from 'node:fs';
    import { requireLastMileEnclosureBinding } from './scripts/lib/last-mile-enclosure-successor-source.mjs';
    import { assertSavedPrivateRuntimeCheckpointReconcileRequest } from './scripts/reconcile-private-runtime-checkpoint.mjs';
    assertSavedPrivateRuntimeCheckpointReconcileRequest();
    const source = JSON.parse(fs.readFileSync(
      process.env.RAVRADAR_OPERATIONAL_WORK + '/current-private-runtime-source.json', 'utf8'));
    const next = requireLastMileEnclosureBinding();
    const integrated = source.modelBinding?.modelBundleSha256 === next.I;
    const continuation = source.contractHashes?.continuationStateContractSha256 === next.T;
    assert.equal(integrated, continuation, 'Saved last-mile source must match both actual I and T');
    fs.appendFileSync(process.env.GITHUB_OUTPUT, 'required=' + (integrated && continuation) + '\n');
    NODE

