edits.current:
- name: Verify installed current050000 predecessor before userdata preparation
  if: (((env.RAVRADAR_USERDATA_PREWRITE_REQUIRED == 'true') && (inputs.restart_archived_weather != true)) && (steps.saved-last-mile-source.outputs.required != 'true')) && (env.RAVRADAR_ACCOUNT_STATISTICS_ASSISTANT_SOURCE_ACTIVE != 'true')
  shell: bash
  env:
    SUPABASE_URL: ${{ secrets.SUPABASE_URL }}
    SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}
  run: |
    set -euo pipefail
    test "${{ steps.current-private-install.outcome }}" != "success"
    test "${{ steps.owner-current-original.outputs.transition_kind }}" != "owner-current-domain-original"
    (
    cd "$RAVRADAR_PREDECESSOR_SOURCE_ROOT"
    node --input-type=module <<'NODE'
    import assert from 'node:assert/strict';
    import fs from 'node:fs';
    import { createHash } from 'node:crypto';
    import { LATEST_REQUIRED_CUTOVER_MIGRATION as latest } from './scripts/integrated-cutover-readiness.mjs';
    assert.equal(latest.version, '20261005000000', 'Userdata predecessor source must end at current050000');
    assert.equal(createHash('sha256').update(fs.readFileSync('supabase/migrations/20261005000000_owner_water_level_only_binding.sql')).digest('hex'),
      '6b161bc71753b52c5728c8b9a03b02d5d0955d0e42e751a3f2a51a6ea6900496', 'Userdata predecessor migration must remain immutable');
    NODE
    node scripts/integrated-cutover-readiness.mjs verify-db
    )

