    import { LATEST_REQUIRED_CUTOVER_MIGRATION as latest, TRIP_BINDING_POLICY_SOURCE_MIGRATION as userdataPolicy, parseSupabaseMigrationList } from './scripts/integrated-cutover-readiness.mjs';
    const rows = parseSupabaseMigrationList(fs.readFileSync(`${process.env.RUNNER_TEMP}/code-only-migrations-before.txt`, 'utf8'));
    const required = latest.version === '20261010120000' && !rows.some(row => row.remote === latest.version);
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_ASSISTANT_PREWRITE_REQUIRED=${required}\n`);
    const userdataPending = !rows.some(row => row.remote === userdataPolicy.version);
    const optedIn = process.env.RAVRADAR_USERDATA_UPGRADE_OPT_IN === 'true';
    if (userdataPending && !optedIn) throw new Error('Pending userdata binding requires explicit existing-owner-export opt-in');
    if (optedIn && (latest.version !== '20261010130000' || !userdataPending
        || !rows.some(row => row.remote === '20261005000000')
        || rows.some(row => row.remote > '20261005000000'))) {
      throw new Error('Userdata upgrade requires installed current050000 and sole pending130000; no intermediary or automatic replay');
    }
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_USERDATA_PREWRITE_REQUIRED=${optedIn && userdataPending}\n`);
    // A later checkpoint-only migration must not suppress the installed
    // userdata storage readback or replay the one-time userdata upgrade.
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_USERDATA_FINAL_REQUIRED=${userdataPolicy.version === '20261010130000'}\n`);
    // This implementation-only repair must never select the normal
    // continuation-repair/recomputation branch for archived weather.
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_CHECKPOINT_CAS_METADATA_ONLY=${latest.version === '20261012200000'}\n`);
    const accountCurrent = latest.version === '20261013210000';
    const accountPending = accountCurrent && !rows.some(row => row.remote === latest.version);
    const accountOptIn = process.env.RAVRADAR_ACCOUNT_ASSISTANT_UPGRADE_OPT_IN === 'true';
    if (accountPending && !accountOptIn) throw new Error('Pending account/assistant successor requires its named opt-in');
    if (accountOptIn && (!accountPending || optedIn
        || !rows.some(row => row.remote === '20261012200000')
        || rows.some(row => row.remote > '20261012200000'))) {
      throw new Error('Account/assistant upgrade requires installed200000 and sole pending20261013210000; no replay');
    }
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_ACCOUNT_ASSISTANT_PREWRITE_REQUIRED=${accountOptIn && accountPending}\n`);
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_ACCOUNT_ASSISTANT_METADATA_ONLY=${accountCurrent}\n`);
    fs.appendFileSync(process.env.GITHUB_ENV, `RAVRADAR_ACCOUNT_ASSISTANT_FINAL_REQUIRED=${accountCurrent}\n`);
    NODE

